-- Function: public.sp_update_inventory_balance_atomic
-- Backup generated on 2026-10-25 20:34:11

CREATE OR REPLACE PROCEDURE public.sp_update_inventory_balance_atomic(IN p_product_id uuid, IN p_location_id uuid, IN p_total_delta integer, IN p_available_delta integer, IN p_reserved_delta integer, IN p_dispatched_delta integer, IN p_on_loan_delta integer, IN p_under_inspection_delta integer, IN p_under_cleaning_delta integer, IN p_damaged_delta integer, IN p_missing_delta integer, IN p_retired_delta integer)  LANGUAGE plpgsql AS $procedure$ DECLARE     v_rows INT; BEGIN     UPDATE inventory_balances SET         total_stock = total_stock + p_total_delta,         available_stock = GREATEST(0, available_stock + p_available_delta),         reserved_stock = GREATEST(0, reserved_stock + p_reserved_delta),         dispatched_stock = GREATEST(0, dispatched_stock + p_dispatched_delta),         on_loan_stock = GREATEST(0, on_loan_stock + p_on_loan_delta),         under_inspection_stock = GREATEST(0, under_inspection_stock + p_under_inspection_delta),         under_cleaning_stock = GREATEST(0, under_cleaning_stock + p_under_cleaning_delta),         damaged_stock = GREATEST(0, damaged_stock + p_damaged_delta),         missing_stock = GREATEST(0, missing_stock + p_missing_delta),         retired_stock = GREATEST(0, retired_stock + p_retired_delta),         updated_at = NOW()     WHERE material_product_id = p_product_id AND location_id = p_location_id;      GET DIAGNOSTICS v_rows = ROW_COUNT;      IF v_rows = 0 THEN         INSERT INTO inventory_balances (             id, material_product_id, location_id, total_stock, available_stock,             reserved_stock, dispatched_stock, on_loan_stock, under_inspection_stock,             under_cleaning_stock, damaged_stock, missing_stock, retired_stock, updated_at         ) VALUES (             gen_random_uuid(), p_product_id, p_location_id,             GREATEST(0, p_total_delta), GREATEST(0, p_available_delta),             GREATEST(0, p_reserved_delta), GREATEST(0, p_dispatched_delta),             GREATEST(0, p_on_loan_delta), GREATEST(0, p_under_inspection_delta),             GREATEST(0, p_under_cleaning_delta), GREATEST(0, p_damaged_delta),             GREATEST(0, p_missing_delta), GREATEST(0, p_retired_delta), NOW()         )         ON CONFLICT (material_product_id, location_id) DO UPDATE SET             total_stock = inventory_balances.total_stock + p_total_delta,             available_stock = GREATEST(0, inventory_balances.available_stock + p_available_delta),             reserved_stock = GREATEST(0, inventory_balances.reserved_stock + p_reserved_delta),             dispatched_stock = GREATEST(0, inventory_balances.dispatched_stock + p_dispatched_delta),             on_loan_stock = GREATEST(0, inventory_balances.on_loan_stock + p_on_loan_delta),             under_inspection_stock = GREATEST(0, inventory_balances.under_inspection_stock + p_under_inspection_delta),             under_cleaning_stock = GREATEST(0, inventory_balances.under_cleaning_stock + p_under_cleaning_delta),             damaged_stock = GREATEST(0, inventory_balances.damaged_stock + p_damaged_delta),             missing_stock = GREATEST(0, inventory_balances.missing_stock + p_missing_delta),             retired_stock = inventory_balances.retired_stock + p_retired_delta,             updated_at = NOW();     END IF; END; $procedure$ ;
